 b=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);page=b.new_page();page.goto('http://127.0.0.1:8000/cbse-mcq-page-settings.js');page.set_content('<main id="setup"></main>')
 result=page.evaluate('''async()=>{const {buildMCQPaperFrame}=await import('./cbse-mcq-page-render.js');const {renderMCQPageSetup}=await import('./cbse-mcq-page-setup-view.js');const make=count=>({id:'PREVIEW',classId:'X',subjectName:'English',count,questions:Array.from({length:count},(_,i)=>({id:'QE'+String(i+1).padStart(3,'0'),verbatim:true,stem:Array.from({length:40},(_,j)=>'Question '+i+' line '+j).join('\\n')}))});let selected=make(1);window.__pageSetup=renderMCQPageSetup(document.querySelector('#setup'),{paper:()=>selected});const options=[...document.querySelectorAll('[name=mcq-pdf-pages] option')].map(n=>n.value),counts=[];for(const n of [1,2,3]){const r=await buildMCQPaperFrame(make(n),{target:4},{fit:false});counts.push({count:r.sheetCount,rough:r.frame.contentDocument.body.innerText.includes('Space for rough work'),numbering:[...r.frame.contentDocument.querySelectorAll('.sheet-number')].map(n=>n.textContent)});r.frame.remove();}let oversized='';try{await buildMCQPaperFrame(make(5),{target:4},{fit:false});}catch(e){oversized=e.message;}return {options,counts,oversized};}''')
